    @property
    def download_dir(self):
        return self._download_dir

    def _set_download_dir(self, download_dir):
        if download_dir and download_dir != '/':
            self._download_dir = download_dir
        else:
            self._download_dir = tempfile.mkdtemp(suffix=self.DOWNLOAD_DIR_SUFFIX)

    @property
    def screenshot_dir(self):
        return self._screenshot_dir

    def _set_default_screenshot_dir(self, screenshot_dir):
        if screenshot_dir:
            self._create_screenshot_dir(screenshot_dir)
        else:
            self._create_screenshot_dir(self._download_dir)

    def _create_screenshot_dir(self, dir_path):
        self._screenshot_dir = os.path.join(dir_path, self.DEBUG_DIR_SUFFIX)
        if not os.path.exists(self._screenshot_dir):
            os.makedirs(self._screenshot_dir)

    def _create_download_checker(self):
        self._download_checker = DownloadChecker(self._download_dir)

    def _create_driver(self, driver, log_level):
        if isinstance(driver, WebDriver):
            self.__driver = driver
            logging.info('WebDriver with ID {} is created'.format(self.__driver))
            return self.__driver

        driver_name = str(driver)
        try:
            driver_obj = self.get_alias_value(driver_name)
        except Exception:
            driver_obj = None

        if driver_obj and isinstance(driver_obj, WebDriver):
            self.__driver = driver_obj
            logging.info('WebDriver named "{}" with ID {} is automatically created'.format(driver_name, self.__driver))
            return self.__driver
        else:
            notification = '''Can not find webdriver named "{}" within robot variable scope!!!
            If you are trying to use self-created webdriver, please read suggestions as below:
            1. check if webdriver name {} is matched with the configured one;
            2. check if correct robot variable scope is set in "set_scope"(global, suite, test can be used)
            method within robot case'''.format(driver_name, driver_name)
            logging.info(notification)

        if driver_name == "Chrome":
            self.__driver = CustomWebDriverChrome(self.download_dir, log_level=log_level)
            logging.info('ChromeWebDriver "{}" with ID {} is automatically created'.format(driver_name, self.__driver))
        elif driver_name == "Firefox":
            self.__driver = CustomWebDriverFirefox(self.download_dir, log_level=log_level)
            logging.info('FirefoxWebDriver "{}" with ID {} is automatically created'.format(driver_name, self.__driver))
        else:
            raise AttributeError('Created webdriver failed, please check browser name "{}"'.format(driver_name))
        return self.__driver

    @staticmethod
    def _precheck():
        check_if_selenium_required_process_exist()

    def _configure_before_login(self, browser, version, download_dir, screenshot_dir, log_level=None):
        self._set_download_dir(download_dir)
        self._set_default_screenshot_dir(screenshot_dir)
        self._create_download_checker()

        if browser == "Firefox" and log_level is None:
            log_level = "trace"
        if browser == "Chrome" and log_level is None:
            log_level = "info"
        driver = self._create_driver(browser, log_level)
        driver.maximize_window()
        sbts_cls = Provider.provide(version)
        sbts = sbts_cls(driver, self._download_checker, self._screenshot_dir)
        return sbts

    def login(self, url, username, password, timeout=60, download_dir=None, screenshot_dir=None, version="SBTS26R1",
              browser='Firefox', wait_session_modal_timeout=10, port=443, ssl=True,
              modal_action_configurations=None, alias=None, log_level=None, readonly=False):
        """
        Keyword for login into sbts web.

        Usage example:

        1) If you want to test feature that only exist in sbts "5G20B", and use "Chrome" as testing browser
        ::
            *** Settings ***
            Library    taf.selenium.sbts_fsm3    WITH NAME      sbts

            *** Variables ***
            ${WEBUI_URL}    xxx.xxx.xxx.xxx
            ${WEBUI_NAME}    Nemuadmin
            ${WEBUI_PWD}     nemuuser

            *** Test Cases ***
            Case Name
            sbts.login   ${WEBUI_URL}   ${WEBUI_NAME}   ${WEBUI_PWD}   version=5G20B    browser=Chrome

        2) If you want to use firefox webdriver created by yourself (please notice that the "driver" has to be
        instance of Webdriver or its child class)
        ::
            *** Settings ***
            Library    taf.selenium.sbts_fsm3    WITH NAME      sbts

            *** Variables ***
            ${download_dir}    xxxx
            ${driver_alias}    myDriver
            ${driver_scope}    suite
            ${WEBUI_URL}    xxx.xxx.xxx.xxx
            ${WEBUI_NAME}    Nemuadmin
            ${WEBUI_PWD}     nemuuser

            *** Test Cases ***
            Case Name
            sbts.create_firefox_web_driver    ${download_dir}    ${driver_alias}
            sbts.set_scope    ${driver_scope}
            sbts.login  ${WEBUI_URL} ${WEBUI_NAME} ${WEBUI_PWD}  downlaod_dir=${download_dir}  browser=${driver_alias}

        3) If you want to start-up several testing browser (login interface supports to pass different alias name to
        distinguish different browser you created)
        ::
            *** Settings ***
            Library    taf.selenium.sbts_fsm3    WITH NAME      sbts

            *** Variables ***
            ${WEBUI_URL}    xxx.xxx.xxx.xxx
            ${WEBUI_NAME}    Nemuadmin
            ${WEBUI_PWD}     nemuuser

            *** Test Cases ***
            Case Name
            sbts.login   ${WEBUI_URL}   ${WEBUI_NAME}  ${WEBUI_PWD}  version=5G20B  browser=Chrome   alias=sbts1
            sbts.login   ${WEBUI_URL}   ${WEBUI_NAME}  ${WEBUI_PWD}  browser=Firefox   alias=sbts2

        For param modal_action_configurations. You can set action configuration to the additional_hardware_detected
        modal like:
        ::
            [{
              modal_name: "Additional hardware detected",
              button: "close", # click Additional hardware detected window's close
                               # button, if it is "Start sync", will click the start
                               # sync button, then click the close button.
              timeout: 20
            }]

        :param url: url to sbts web
        :type url: str
        :param username: username
        :type username: str
        :param password: password
        :type password: str
        :param timeout: timeout
        :type timeout: int
        :param download_dir: file downloaded dir
        :type download_dir: str
        :param screenshot_dir: screenshot dir
        :type screenshot_dir: str
        :param version: version string, defalut is SBTS21A
        :type version: str
        :param browser: WebDriver instance or "Chrome" or "Firefox" or alias name for self-created webdriver
        :type browser: Optional[WebDriver, str]
        :param wait_session_modal_timeout: timeout for waiting session establishment error modal
        :type wait_session_modal_timeout: int
        :param port: port
        :type port: int or str
        :param ssl: param to select ssl checkbox on webem, default is True
        :type ssl: boolean
        :param modal_action_configurations: pass the modal action configurations with dict list
        :type modal_action_configurations: list
        :param alias: (optional) alias that the new sbts object will be identified by
                      If not specified, default alias is used: "None"
        :type alias: str
        :param log_level: Firefox supported log level "fatal", "error", "warn", "info", "config", "debug", "trace",
                          Chrome supported log level "severe", "warning", "info", "debug", "off", "all",
                          Firefox will use "trace" as log level when this param is None,
                          Chrome will use "info" as log level when this param is None.
        :type log_level: str
        :param readonly: if readonly checkbox should be selected, default is False
        :type readonly: bool
        :return: error msg if it exists after login
        :rtype: None or str
        """
        self._precheck()
        sbts = self._configure_before_login(browser, version, download_dir, screenshot_dir, log_level)
        login_msg = sbts.login(url, username, password, self._download_checker, self._screenshot_dir,
                               wait_session_modal_timeout, port, ssl, timeout, modal_action_configurations, readonly)
        self.store.add(sbts, alias)
        self.lookup_handler.store = self.store
        return login_msg

    def login_with_offline_mode(self, file_path, download_dir=None, screenshot_dir=None,
                                version=None, browser='Firefox', alias=None):
        """
        Keyword for opening html file under offline mode.

        :param file_path: html file path
        :param download_dir: file downloaded dir
        :type download_dir: str
        :param screenshot_dir: screenshot dir
        :type screenshot_dir: str
        :param version: version string, can be "5G20B", default is None
        :type version: str
        :param browser: WebDriver instance or "Chrome" or "Firefox"
        :type browser: Optional[WebDriver, str]
        :param alias: (optional) alias that the new sbts object will be identified by
                      If not specified, default alias is used: "None"
        :type alias: str
        """
        sbts = self._configure_before_login(browser, version, download_dir, screenshot_dir)
        sbts.login_with_offline_mode(file_path, self._download_checker, self._screenshot_dir)
        self.store.add(sbts, alias)

