    @catch_interface_exception
    @catch_intercepted_click_exception
    @lookup_handler.implicit_lookup
    def start_5g_downlink_test(self, sbts=None, **kwargs):
        """
        Starts 5G downlink test on Diagnostic > Test Models > 5G Downlink page.

        .. note::
            Keyword enable_test_dedicated_state should be be used before this one.

        Params supported by 5G20B list as below:
        ::
            local_cell
            test_model
            p_max
            polarization
            physical_cell_id
            beam_id

        Params supported by 5G21A list as below:
        ::
            local_cell
            test_model
            p_max
            polarization
            physical_cell_id
            beam_id
            nrarfcn_downlink (for FDD)
            nrarfcn_uplink (for FDD)
            nrarfcn (for TDD)

        Params supported by SBTS21B list as below:
        ::
            local_cell
            test_model
            p_max
            polarization
            physical_cell_id
            beam_id
            nrarfcn_downlink (for FDD)
            nrarfcn_uplink (for FDD)
            nrarfcn (for TDD)

        Params supported by SBTS22R4 list as below:
        ::
            local_cell
            test_model
            p_max
            polarization
            physical_cell_id
            beam_id
            nrarfcn_downlink (for FDD)
            nrarfcn_uplink (for FDD)
            nrarfcn (for TDD)
            type_of_load (default None)
            level_of_load_flat (exist when type_of_load is faltLoad, default None)
            level_of_load_burst (exist when type_of_load is burstLoad, default None)
            spec_ssb_beam_pattern (exist when type_of_load is faltLoad and level_of_load_flat is Low, default None)

        Params supported by SBTS23R1 list as below:
        ::
            local_cell
            test_model
            p_max
            polarization
            physical_cell_id
            beam_id
            nrarfcn_downlink (for FDD)
            nrarfcn_uplink (for FDD)
            nrarfcn (for TDD)
            type_of_load (default None)
            level_of_load_flat (exist when type_of_load is faltLoad, default None)
            level_of_load_burst (exist when type_of_load is burstLoad, default None)
            spec_ssb_beam_pattern (exist when type_of_load is faltLoad and level_of_load_flat is Low, default None)
            power_backoff (default None)
            ru_mode (default None)
            mimo_rank (default None)

        Params supported by SBTS24R2 list as below:
        ::
            local_cell
            test_model
            p_max
            polarization
            physical_cell_id
            beam_id
            nrarfcn_downlink (for FDD)
            nrarfcn_uplink (for FDD)
            nrarfcn (for TDD)
            type_of_load (default None)
            level_of_load_flat (exist when type_of_load is faltLoad, default None)
            level_of_load_burst (exist when type_of_load is burstLoad, default None)
            spec_ssb_beam_pattern (exist when type_of_load is faltLoad and level_of_load_flat is Low, default None)
            power_backoff (default None)
            ru_mode (default None)
            mimo_rank (default None)
            enable_vswr (default False)

        Params supported by SBTS24R3 list as below:
        ::
            local_cell
            test_model
            p_max
            polarization
            physical_cell_id
            beam_id
            nrarfcn_downlink (for FDD)
            nrarfcn_uplink (for FDD)
            nrarfcn (for TDD)
            type_of_load (default None, this param strongly depends on test_model. e.g. NR-FR1-TM1.1.ETSI)
            spec_ssb_beam_pattern (exist when type_of_load is faltLoad and level_of_load_flat is Low, default None)
            power_backoff (default None)
            ru_mode (default None)
            mimo_rank (default None)
            enable_vswr (default False)
            level_of_load_slot_wise
        """
        sbts.diagnostic.downlink.navigate_to()
        sbts.diagnostic.downlink.start_test(**kwargs)

