    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def configure_iq_capture(self, sbts=None, **kwargs):
        """
        Keyword for configuring iq capture

        Params supported classical version<SBTS21A as below:
        ::
            bbmod (mandatory),
            ul_subcell_index (mandatory)
            dl_subcell_index (mandatory)
            enable_capture_on_event (mandatory)

        Params supported sbts version>=SBTS21A and use "NR" technology as below:
        ::
            bbmod (mandatory),
            ul_subcell_index_list (mandatory)
            dl_subcell_index_list (mandatory)
            enable_capture_on_event (mandatory)

        Params supported sbts version>=SBTS21A and use "LTE" technology as below:
        ::
            bbmod (mandatory)
            lte_ul_cell_ids (mandatory)
            lte_dl_cell_ids (mandatory)
            enable_capture_on_event (mandatory)

        Params supported sbts version==SBTS23R2 as below:
        ::
            ul_subcell_index_list (mandatory)
            dl_subcell_index_list (mandatory)
            lte_ul_cell_ids (optional)
            lte_dl_cell_ids (optional)
            enable_capture_on_event (mandatory)

        .. note::
            bbmod is not be supported anymore under SBTS23R2

        Params supported sbts version==SBTS23R3 as below:
        ::
            enable_capture_on_event (mandatory)
            capture_event (optional)
            buffer_cycle (optional)
            capture_frame_offset (optional)
            radio_configurations (optional)
            ul_subcell_index_list (optional)
            dl_subcell_index_list (optional)
            lte_ul_cell_ids (optional)
            lte_dl_cell_ids (optional)
            buffer_cycle (optional)
            capture_frame_offset (optional)
            radio_configurations (optional)

        Params supported sbts version==SBTS25R3 as below:
            enable_capture_on (mandatory)
            capture_from (optional)
            profile  (optional)
            ul_subcell_index_list (optional)
            dl_subcell_index_list (optional)
            lte_ul_cell_ids  (optional)
            lte_dl_cell_ids (optional)
            buffer_cycle (optional)
            capture_frame_offset (optional)
            radio_configurations (optional)

        If you want to enable capture on event but not capture event from BBU and RU under version SBTS23R3,
        example as below:
        ::
            configure_iq_capture(
                enable_capture_on_event=True,
                ul_subcell_index_list=["[SMOD_R-1(ASOE)] [PCI: 18]NRCELL-1: Subcell 0",
                                       "[SMOD_R-1(ASOE)] [PCI: 31]NRCELL-2: Subcell 1"],
                dl_subcell_index_list=["[SMOD_R-1(ASOE)] [PCI: 22]NRCELL-1: Subcell 0",
                                       "[SMOD_R-1(ASOE)] [PCI: 45]NRCELL-2: Subcell 1"]
            )

        If you want to capture on event from BBU and RU under version SBTS23R3, example as below:
        ::
            configure_iq_capture(
                enable_capture_on_event=True,
                capture_event=True,
                ul_subcell_index_list=["[SMOD_R-1(ASOE)] [PCI: 18]NRCELL-1: Subcell 0",
                                       "[SMOD_R-1(ASOE)] [PCI: 31]NRCELL-2: Subcell 1"],
                buffer_cycle="1024_FRAMES",
                capture_frame_offset="23",
                radio_configurations={
                    "RMOD-2/RMOD_R-2(AQQK)": {
                        "Antenna list": "Group1(-45 polarization, +45 polarization)",
                        "-45 Polarization": [0, 22, 18],
                        "+45 Polarization": [2, 16, 20],
                        "capture_activity_timer": 3
                    },
                    "RMOD-1/RMOD_R-1(AKQJ)": {
                        "Antenna list": "Group4(-45 polarization)",
                        "-45 Polarization": ['ANT4'],
                        "capture_activity_timer": 4
                    }
                }
            )
        If you want to capture on event from BBU and RU under version SBTS25R3, example as below:

            configure_iq_capture(
                ul_subcell_index_list=['[BBMOD_R-1(ABIP)] [PCI: 11]NRCELL-1: Subcell 0'],
                dl_subcell_index_list=['[BBMOD_R-1(ABIP)] [PCI: 11]NRCELL-1: Subcell 0'],
                enable_capture_on="Event",
                capture_from="BBU")

            configure_iq_capture(
                enable_capture_on="Event",
                capture_from="BBU and RU",
                profile="[UL_PROFILE_3][TD][Event][7-2a/7-2e]Timing issues debugging",
                ul_subcell_index_list=["[BBMOD_R-1(ABIP)] [PCI: 100][7-2a]NRCELL-10: Subcell 1"],
                buffer_cycle="32_FRAMES",
                capture_frame_offset=10,
                radio_configurations={
                    "RMOD-1/RMOD_R-2(AKQJ)": {
                        "Antenna list": "Set1(-45 polarization, +45 polarization)",
                        "-45 Polarization": ["ANT1"],
                        "+45 Polarization": ["ANT5"],
                        "capture_activity_timer": 3}
                        }
            )

        :param bbmod: bbmod value
        :type bbmod: str
        :param ul_subcell_index: ul subcell index
        :type ul_subcell_index: int or str
        :param dl_subcell_index: dl subcell index
        :type dl_subcell_index: str or int
        :param ul_subcell_index_list: list of ul subcell index, list[int] or list[str]
        :type ul_subcell_index_list: list
        :param dl_subcell_index_list: dl subcell index, list[int] or list[str]
        :type dl_subcell_index_list: list
        :param lte_ul_cell_ids: lte ul cell ids, list[int] or list[str]
        :type lte_ul_cell_ids: list
        :param lte_dl_cell_ids: lte dl cell ids, list[int] or list[str]
        :type lte_dl_cell_ids: list
        :param enable_capture_on_event: if True, the capture on event option will be enabled.
        :type enable_capture_on_event: bool
        :param enable_capture_on: if "Event" or "Blind" can be passed in, default is "Event"
        :type enable_capture_on: str
        :param capture_from: if "BBU" or "BBU and RU" can be passed in, default is "BBU"
        :type capture_from: str
        :param profile: profile name
        :type profile: str
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
                                  If not specified, default alias is used: "None"
        :type sbts: str
        :return: string which represents configuring status
        :rtype: str
        """
        sbts.diagnostic.debug_tracing.navigate_to()
        return sbts.diagnostic.debug_tracing.configure_iq_capture(**kwargs)

