    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def start_diagnostic_check(self, scope="Full diagnostic check", timeout=180, sbts=None, **kwargs):
        """
        kw for starting diagnostic check under "Diagnostic Check" page

        .. note::
            If you choose any options marked as 'RST' under "Customized diagnostic check" will cause radio reset,
            this will take long time to check, please raise up default timeout 180 to larger number.

        For example,
        ::
            # select "Full diagnostic check" scope but not select "Allow service impact" checkbox
            sbts_instance.start_diagnostic_check(scope="Full diagnostic check")

            # select ""Full diagnostic check" scope and select "Allow service impact" checkbox
            sbts_instance.start_diagnostic_check(scope="Full diagnostic check", allow_service_impact=True)

            # select "Customized diagnostic check" scope, select all bts and radio checkpoints
            sbts_instance.start_diagnostic_check(scope="Customized diagnostic check")

            # select "Customized diagnostic check" scope, select particular bts and radio checkpoints
            bts_checkpoints = ["6 - FileDirectory.xml integrity on the passive partition",
                               "31 - Active critical alarms"]
            radio_checkpoints = {
                "RMOD-1 / RMOD_R-1 (AEQY)": [
                    '21 - Radio Module ethernet link',
                    '42 - RU Temperature sensor'
                ]
            }
            sbts_instance.start_diagnostic_check(
                scope="Customized diagnostic check",
                bts_checkpoints=bts_checkpoints,
                radio_checkpoints=radio_checkpoints
            )

            # select "Customized diagnostic check" scope, select all bts and part of radio checkpoints
            radio_checkpoints = {
                "RMOD-1 / RMOD_R-1 (AEQY)": [
                    '21 - Radio Module ethernet link',
                    '42 - RU Temperature sensor'
                ]
            }
            sbts_instance.start_diagnostic_check(
                scope="Customized diagnostic check",
                radio_checkpoints=radio_checkpoints
            )

            # select "Customized diagnostic check" scope, select part of bts and all radio checkpoints
            bts_checkpoints = ["6 - FileDirectory.xml integrity on the passive partition",
                               "31 - Active critical alarms"]
            sbts_instance.start_diagnostic_check(
                scope="Customized diagnostic check",
                bts_checkpoints=bts_checkpoints
            )

        :param scope: scope name
        :type scope: str
        :param timeout: timeout
        :type param: int
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
                     If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.diagnostic.diagnostic_check.navigate_to()
        return sbts.diagnostic.diagnostic_check.start_diagnostic_check(scope, int(timeout), **kwargs)

